// ServerInterface represents all server handlers.
type ServerInterface interface {
	// Healthz Liveness
	// (GET /healthz)
	Healthz(w http.ResponseWriter, r *http.Request)
	// Readyz Readiness (database reachable)
	// (GET /readyz)
	Readyz(w http.ResponseWriter, r *http.Request)
	// AcceptInvite Accept an invitation, join the tenant and open a session
	// (POST /v1/auth/invite/accept)
	AcceptInvite(w http.ResponseWriter, r *http.Request)
	// PreviewInvite See an invitation before accepting it, without using it
	// (POST /v1/auth/invite/preview)
	PreviewInvite(w http.ResponseWriter, r *http.Request)
	// Login Exchange email and password for an access token and a refresh token
	// (POST /v1/auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// Logout Revoke the refresh token family of this session
	// (POST /v1/auth/logout)
	Logout(w http.ResponseWriter, r *http.Request, params LogoutParams)
	// RequestMagicLink Email a one time login link
	// (POST /v1/auth/magic-link)
	RequestMagicLink(w http.ResponseWriter, r *http.Request, params RequestMagicLinkParams)
	// AcceptMagicLink Open a session with a magic link
	// (POST /v1/auth/magic-link/accept)
	AcceptMagicLink(w http.ResponseWriter, r *http.Request)
	// Refresh Rotate the refresh token and get a new access token
	// (POST /v1/auth/refresh)
	Refresh(w http.ResponseWriter, r *http.Request, params RefreshParams)
	// Register Create an account, its first tenant and the owner membership
	// (POST /v1/auth/register)
	Register(w http.ResponseWriter, r *http.Request, params RegisterParams)
	// SwitchTenant Move the session to another of the caller's tenants, no password
	// (POST /v1/auth/switch-tenant)
	SwitchTenant(w http.ResponseWriter, r *http.Request, params SwitchTenantParams)
	// ListCloses The closed periods of the active tenant, newest first
	// (GET /v1/closes)
	ListCloses(w http.ResponseWriter, r *http.Request, params ListClosesParams)
	// ClosePeriod Close a period of the active tenant (operator)
	// (POST /v1/closes)
	ClosePeriod(w http.ResponseWriter, r *http.Request, params ClosePeriodParams)
	// GetClose One closed period of the active tenant, with its summary
	// (GET /v1/closes/{closeId})
	GetClose(w http.ResponseWriter, r *http.Request, closeId openapi_types.UUID)
	// ListInvoices Invoices of the active tenant, newest first
	// (GET /v1/documents/invoices)
	ListInvoices(w http.ResponseWriter, r *http.Request, params ListInvoicesParams)
	// UploadInvoice Upload a supplier invoice (PDF or image)
	// (POST /v1/documents/invoices)
	UploadInvoice(w http.ResponseWriter, r *http.Request, params UploadInvoiceParams)
	// GetInvoice An invoice with every field's source and confidence
	// (GET /v1/documents/invoices/{invoiceId})
	GetInvoice(w http.ResponseWriter, r *http.Request, invoiceId openapi_types.UUID)
	// ListExports What the client can download, with row counts
	// (GET /v1/exports)
	ListExports(w http.ResponseWriter, r *http.Request)
	// GetExport Download one export as CSV
	// (GET /v1/exports/{kind})
	GetExport(w http.ResponseWriter, r *http.Request, kind GetExportParamsKind, params GetExportParams)
	// GetInbox The tenant's statement mailbox, its address and authorized senders
	// (GET /v1/inbox)
	GetInbox(w http.ResponseWriter, r *http.Request)
	// RotateInboxAddress Create the mailbox address, or replace it with a new one (owner)
	// (POST /v1/inbox/address)
	RotateInboxAddress(w http.ResponseWriter, r *http.Request, params RotateInboxAddressParams)
	// ListInboxReceipts Receipts of the mail the mailbox got, newest first
	// (GET /v1/inbox/receipts)
	ListInboxReceipts(w http.ResponseWriter, r *http.Request)
	// AddInboxSender Authorize a sender for the mailbox (owner)
	// (POST /v1/inbox/senders)
	AddInboxSender(w http.ResponseWriter, r *http.Request, params AddInboxSenderParams)
	// RemoveInboxSender Stop accepting mail from a sender (owner)
	// (DELETE /v1/inbox/senders/{senderId})
	RemoveInboxSender(w http.ResponseWriter, r *http.Request, senderId openapi_types.UUID)
	// ListAccounts Accounts of the active tenant
	// (GET /v1/ledger/accounts)
	ListAccounts(w http.ResponseWriter, r *http.Request)
	// CreateAccount Register a bank or Mercado Pago account (owner or operator)
	// (POST /v1/ledger/accounts)
	CreateAccount(w http.ResponseWriter, r *http.Request, params CreateAccountParams)
	// UploadStatement Upload a statement export of the account
	// (POST /v1/ledger/accounts/{accountId}/statements)
	UploadStatement(w http.ResponseWriter, r *http.Request, accountId AccountId, params UploadStatementParams)
	// ListFiles Statement files uploaded, accepted or quarantined, newest first
	// (GET /v1/ledger/files)
	ListFiles(w http.ResponseWriter, r *http.Request, params ListFilesParams)
	// ListMovements Movements of one month, in date and line order
	// (GET /v1/ledger/movements)
	ListMovements(w http.ResponseWriter, r *http.Request, params ListMovementsParams)
	// ListQuarantine Files that did not enter, with the reason
	// (GET /v1/ledger/quarantine)
	ListQuarantine(w http.ResponseWriter, r *http.Request)
	// ListOpenItems Open items nothing settles yet, to link a movement by hand
	// (GET /v1/matching/items)
	ListOpenItems(w http.ResponseWriter, r *http.Request, params ListOpenItemsParams)
	// ListMatches Matches waiting in a tray
	// (GET /v1/matching/matches)
	ListMatches(w http.ResponseWriter, r *http.Request, params ListMatchesParams)
	// DecideMatch Decide on a match in the Suggested or Exceptions tray
	// (POST /v1/matching/matches/{matchId}/decision)
	DecideMatch(w http.ResponseWriter, r *http.Request, matchId string, params DecideMatchParams)
	// DecideMovement Decide on a movement with no candidate (the client, then the operator)
	// (POST /v1/matching/movements/{movementId}/decision)
	DecideMovement(w http.ResponseWriter, r *http.Request, movementId openapi_types.UUID, params DecideMovementParams)
	// ListPending Movements waiting for a person, from the latest run of each one
	// (GET /v1/matching/pending)
	ListPending(w http.ResponseWriter, r *http.Request, params ListPendingParams)
	// RunMatching Run the matching engine over a month (owner or operator)
	// (POST /v1/matching/runs)
	RunMatching(w http.ResponseWriter, r *http.Request, params RunMatchingParams)
	// GetMe The caller, the active tenant and every membership
	// (GET /v1/me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// UpdateMe Set the caller's own name
	// (PATCH /v1/me)
	UpdateMe(w http.ResponseWriter, r *http.Request)
	// GetMyTenant Onboarding status of the active tenant (portal home)
	// (GET /v1/me/tenant)
	GetMyTenant(w http.ResponseWriter, r *http.Request)
	// ListMetrics Results panel of the active tenant for a month
	// (GET /v1/metrics)
	ListMetrics(w http.ResponseWriter, r *http.Request, params ListMetricsParams)
	// ListMembers Members of the active tenant
	// (GET /v1/tenant/members)
	ListMembers(w http.ResponseWriter, r *http.Request)
	// AddMember Add a person to the active tenant (owner, or operator for the first owner)
	// (POST /v1/tenant/members)
	AddMember(w http.ResponseWriter, r *http.Request, params AddMemberParams)
	// RemoveMember Remove a person from the active tenant (owner only)
	// (DELETE /v1/tenant/members/{userId})
	RemoveMember(w http.ResponseWriter, r *http.Request, userId openapi_types.UUID)
	// ListTenants Tenants where the caller is operator or accountant (operator console)
	// (GET /v1/tenants)
	ListTenants(w http.ResponseWriter, r *http.Request)
}

